import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 26
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    parsed_rows = []
    for row in reader:
        parsed_rows.append(row if row else [""])

    if not parsed_rows:
        return {"columns": [""] * expected_width, "rows": []}

    width = max(expected_width, len(parsed_rows[0]), max(map(len, parsed_rows)))
    columns = parsed_rows[0] + [""] * (width - len(parsed_rows[0]))
    rows = [
        row + [""] * (width - len(row))
        for row in parsed_rows[1:]
    ]
    return {"columns": columns, "rows": rows}
